                        NR[rr] = True
                        CH[rr] = None
                val = ch_to_val(ch, first) - f(ns, NR, not first)
                if val > ans:
                    ans = val
        memo[key] = ans
        return ans

    start_val = ch_to_val(G[0][0], True)
    result = start_val - f(0, [True], False)
    if result > 0:
        print("FIRST")
    elif result < 0:
        print("SECOND")
    else:
        print("DRAW")

